    def factory(*args, **kwargs):
        client = DummyClient(*args, **kwargs)
        holder["client"] = client
        return client

    monkeypatch.setattr(cli, "ApiClient", factory)
    code = cli.main(["/users", "-p", "page=2", "-p", "q=hi"])
    out = capsys.readouterr().out
    assert code == 0
    assert json.loads(out) == {"path": "/users", "params": {"page": "2", "q": "hi"}}


